def salary_analyzer(employees):
    """Calculate average salary for a list of employees.
    Returns average salary as float, 0.0 for empty list, None for invalid input.
    """
    if employees is None:
        return None
    if not isinstance(employees, list):
        return None
    if not employees:
        return 0.0
    total_salary = 0.0
    for emp in employees:
        if not isinstance(emp, dict):
            return None
        if 'salary' not in emp:
            return None
        salary = emp['salary']
        if not isinstance(salary, (int, float)):
            return None
        total_salary += salary
    return total_salary / len(employees)

